function toRoman(n) {
  if (typeof n !== 'number' || !Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError();
  }

  const values = [
    { num: 1000, str: 'M' },
    { num: 900, str: 'CM' },
    { num: 500, str: 'D' },
    { num: 400, str: 'CD' },
