    { num: 5, str: 'V' },
    { num: 4, str: 'IV' },
    { num: 1, str: 'I' }
  ];

  let result = '';
  for (const { num, str } of values) {
    while (n >= num) {
      result += str;
      n -= num;
    }
  }
  return result;
}

function fromRoman(s) {
  if (typeof s !== 'string') {
    throw new TypeError();
  }

  const romanValues = {
    'I': 1,
    'V': 5,
    'X': 10,
    'L': 50,
    'C': 100,
    'D': 500,
    'M': 1000
  };

  // Valid subtractive pairs
  const validPairs = new Set(['IV', 'IX', 'XL', 'XC', 'CD', 'CM']);

  let result = 0;
  let i = 0;

  while (i < s.length) {
    const char = s[i];

    // Check if character is valid Roman numeral
    if (!(char in romanValues)) {
      throw new SyntaxError();
    }

    // Check for subtractive pair
    if (i + 1 < s.length) {
      const pair = s.substring(i, i + 2);
      if (validPairs.has(pair)) {
        result += romanValues[pair[1]] - romanValues[pair[0]];
        i += 2;
        continue;
      }
    }

    // Single character
    result += romanValues[char];
    i += 1;
  }

  // Validate that the result is in valid range and that the Roman numeral is in standard form
  if (result < 1 || result > 3999) {
    throw new SyntaxError();
  }

  // Verify that converting back to Roman gives us the original string
  if (toRoman(result) !== s) {
    throw new SyntaxError();
  }

  return result;
}

module.exports = { toRoman, fromRoman };
